   │  │  └─ bountyProgramsApi.ts
   │  ├─ components/
   │  │  ├─ Layout/
   │  │  │  ├─ Header.tsx
   │  │  │  └─ Footer.tsx
   │  │  ├─ SearchForm.tsx
