   └─ public/
      └─ favicon.ico
```

---

## 4. Backend details

### 4.1 Dependencies (backend)

`backend/package.json` (core deps):

```jsonc
{
  "name": "bounty-hunter-backend",
  "version": "1.0.0",
  "main": "dist/index.js",
  "scripts": {
    "dev": "ts-node-dev --respawn src/index.ts",
    "build": "tsc",
    "start": "node dist/index.js",
    "migrate": "prisma migrate dev",
    "lint": "eslint src --ext .ts",
    "test": "jest"
  },
  "dependencies": {
    "@prisma/client": "^5.0.0",
    "axios": "^1.6.0",
    "cors": "^2.8.5",
    "dotenv": "^16.0.0",
    "express": "^4.19.0",
    "helmet": "^7.0.0",
    "morgan": "^1.10.0",
    "node-cron": "^3.0.0"
  },
  "devDependencies": {
    "@types/express": "^4.17.21",
    "@types/node": "^20.0.0",
    "eslint": "^9.0.0",
    "jest": "^29.0.0",
    "prisma": "^5.0.0",
    "ts-jest": "^29.0.0",
    "ts-node-dev": "^2.0.0",
    "typescript": "^5.4.0"
  }
}
```

### 4.2 Database schema (Prisma + SQLite for start)

`backend/prisma/schema.prisma`:

```prisma
datasource db {
  provider = "sqlite"              // can change to postgresql later
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

model BountyProgram {
  id              Int       @id @default(autoincrement())
  name            String
  platform        String?   // e.g., "HackerOne", "Bugcrowd", "Standalone"
  url             String
  minBounty       Int?      // in USD cents to avoid floating problems
  maxBounty       Int?
  rewardType      String?   // "cash", "swag", "points", etc.
  isPublic        Boolean   @default(true)
  reputationScore Float?    // derived metric (e.g., from reviews/age/activity)
  easeOfEntry     String?   // "easy", "medium", "hard" (subjective scoring)
  vulnerabilityTypes String? // CSV or JSON string for basic impl

  scopeSummary    String?   // free text summary of the scope
  createdAt       DateTime  @default(now())
  updatedAt       DateTime  @updatedAt
  source          String?   // where we got this data
}
```

### 4.3 Environment config

`backend/.env.example`:

```bash
PORT=4000
DATABASE_URL="file:./dev.db"
NODE_ENV=development
```

### 4.4 Server entry

`backend/src/index.ts`:

```ts
import { config } from "dotenv";
config();

import { createServer } from "http";
import app from "./app";
import { prisma } from "./db/client";

const PORT = process.env.PORT || 4000;

async function start() {
  try {
    await prisma.$connect();
    const server = createServer(app);

    server.listen(PORT, () => {
      console.log(`Backend running on http://localhost:${PORT}`);
    });
  } catch (err) {
    console.error("Failed to start server:", err);
    process.exit(1);
  }
}

start();
```

### 4.5 Express app configuration

`backend/src/app.ts`:

```ts
import express from "express";
import cors from "cors";
import helmet from "helmet";
import morgan from "morgan";

import bountyProgramsRouter from "./routes/bountyPrograms";
import { errorHandler } from "./utils/errorHandler";

const app = express();

// Basic security headers
app.use(helmet());

// Enable CORS for frontend dev
app.use(
  cors({
    origin: "http://localhost:5173", // adjust for frontend
    credentials: true
  })
);

// Parse JSON bodies
app.use(express.json());

// Logging
app.use(morgan("dev"));

app.get("/health", (_req, res) => {
  res.json({ status: "ok" });
});

app.use("/api/bounty-programs", bountyProgramsRouter);

// Global error handler
app.use(errorHandler);

export default app;
```

### 4.6 DB client

`backend/src/db/client.ts`:

```ts
import { PrismaClient } from "@prisma/client";

export const prisma = new PrismaClient();
```

### 4.7 Routes and controller

`backend/src/routes/bountyPrograms.ts`:

```ts
import { Router } from "express";
import {
  getBountyPrograms,
  getBountyProgramById
} from "../controllers/bountyProgramController";

const router = Router();

// GET /api/bounty-programs?minBounty=&maxBounty=&platform=&rewardType=&search=
router.get("/", getBountyPrograms);

// GET /api/bounty-programs/:id
router.get("/:id", getBountyProgramById);

export default router;
```

`backend/src/controllers/bountyProgramController.ts`:

```ts
import { Request, Response, NextFunction } from "express";
import * as service from "../services/bountyProgramService";

// Controller functions focus on HTTP details only
export async function getBountyPrograms(
  req: Request,
  res: Response,
  next: NextFunction
) {
  try {
    const {
      minBounty,
      maxBounty,
      platform,
      rewardType,
      search
    } = req.query;

    const criteria = {
      minBounty: minBounty ? Number(minBounty) : undefined,
      maxBounty: maxBounty ? Number(maxBounty) : undefined,
      platform: platform?.toString(),
      rewardType: rewardType?.toString(),
      search: search?.toString()
    };

    const result = await service.searchBountyPrograms(criteria);
    res.json(result);
  } catch (err) {
    next(err);
  }
}

export async function getBountyProgramById(
  req: Request,
  res: Response,
  next: NextFunction
) {
  try {
    const id = Number(req.params.id);
    const program = await service.getBountyProgram(id);
    if (!program) {
      return res.status(404).json({ message: "Program not found" });
    }
    res.json(program);
  } catch (err) {
    next(err);
  }
}
```

### 4.8 Service layer

`backend/src/models/selectionCriteria.ts`:

```ts
export interface SelectionCriteria {
  minBounty?: number;
  maxBounty?: number;
  platform?: string;
  rewardType?: string;
  search?: string; // keyword search on name / scopeSummary
}
```

`backend/src/services/bountyProgramService.ts`:

```ts
import { prisma } from "../db/client";
import { SelectionCriteria } from "../models/selectionCriteria";

/**
 * Search bounty programs based on user criteria.
 * NOTE: This is a basic implementation; later we can add
 * full-text search, scoring, and more advanced filters.
 */
export async function searchBountyPrograms(criteria: SelectionCriteria) {
  const where: any = {};

  if (criteria.minBounty !== undefined) {
    where.minBounty = { gte: criteria.minBounty };
  }
  if (criteria.maxBounty !== undefined) {
    where.maxBounty = { lte: criteria.maxBounty };
  }
  if (criteria.platform) {
    where.platform = { equals: criteria.platform, mode: "insensitive" };
  }
  if (criteria.rewardType) {
    where.rewardType = { equals: criteria.rewardType, mode: "insensitive" };
  }
  if (criteria.search) {
    where.OR = [
      { name: { contains: criteria.search, mode: "insensitive" } },
      { scopeSummary: { contains: criteria.search, mode: "insensitive" } }
    ];
  }

  const programs = await prisma.bountyProgram.findMany({
    where,
    orderBy: {
      reputationScore: "desc"
    },
    take: 50 // limit to avoid huge payload
  });

  return programs;
}

export async function getBountyProgram(id: number) {
  return prisma.bountyProgram.findUnique({ where: { id } });
}
```

### 4.9 Data ingestion service (placeholder)

`backend/src/services/dataIngestionService.ts`:

```ts
import { prisma } from "../db/client";

/**
 * For MVP we'll seed from a local JSON file.
 * Later this can call:
 * - HackerOne / Bugcrowd / Intigriti public endpoints (if allowed)
 * - Official disclosure pages
 * - Scrapers with respect to robots.txt and ToS
 */
export async function seedFromLocalJson(path: string) {
  // Import dynamically to avoid bundling large file
  const data = (await import(path)).default as any[];

  for (const raw of data) {
    await prisma.bountyProgram.upsert({
      where: { url: raw.url },
      update: {
        name: raw.name,
        platform: raw.platform,
        minBounty: raw.minBounty,
        maxBounty: raw.maxBounty,
        rewardType: raw.rewardType,
        isPublic: raw.isPublic,
        reputationScore: raw.reputationScore,
        easeOfEntry: raw.easeOfEntry,
        vulnerabilityTypes: raw.vulnerabilityTypes?.join(","),
        scopeSummary: raw.scopeSummary,
        source: raw.source
      },
      create: {
        name: raw.name,
        platform: raw.platform,
        url: raw.url,
        minBounty: raw.minBounty,
        maxBounty: raw.maxBounty,
        rewardType: raw.rewardType,
        isPublic: raw.isPublic ?? true,
        reputationScore: raw.reputationScore,
        easeOfEntry: raw.easeOfEntry,
        vulnerabilityTypes: raw.vulnerabilityTypes?.join(","),
        scopeSummary: raw.scopeSummary,
        source: raw.source
      }
    });
  }
}
```

---

## 5. Frontend details

### 5.1 Dependencies (frontend)

`frontend/package.json`:

```jsonc
{
  "name": "bounty-hunter-frontend",
  "version": "1.0.0",
  "scripts": {
    "dev": "vite",
    "build": "vite build",
    "preview": "vite preview",
    "lint": "eslint src --ext .ts,.tsx"
  },
  "dependencies": {
    "axios": "^1.6.0",
    "react": "^18.2.0",
    "react-dom": "^18.2.0"
  },
  "devDependencies": {
    "@types/react": "^18.0.0",
    "@types/react-dom": "^18.0.0",
    "@vitejs/plugin-react-swc": "^3.0.0",
    "eslint": "^9.0.0",
    "typescript": "^5.4.0",
    "vite": "^5.0.0"
  }
}
```

### 5.2 Types and API layer

`frontend/src/types/bountyProgram.ts`:

```ts
export interface BountyProgram {
  id: number;
  name: string;
  platform?: string | null;
  url: string;
  minBounty?: number | null;
  maxBounty?: number | null;
  rewardType?: string | null;
  isPublic: boolean;
  reputationScore?: number | null;
  easeOfEntry?: string | null;
  vulnerabilityTypes?: string | null;
  scopeSummary?: string | null;
  createdAt: string;
  updatedAt: string;
  source?: string | null;
}
```

`frontend/src/api/bountyProgramsApi.ts`:

```ts
import axios from "axios";
import { BountyProgram } from "../types/bountyProgram";

const api = axios.create({
  baseURL: "http://localhost:4000/api"
});

export async function fetchBountyPrograms(params: {
  minBounty?: number;
  maxBounty?: number;
  platform?: string;
  rewardType?: string;
  search?: string;
}) {
  const res = await api.get<BountyProgram[]>("/bounty-programs", {
    params
  });
  return res.data;
}

export async function fetchBountyProgramById(id: number) {
  const res = await api.get<BountyProgram>(`/bounty-programs/${id}`);
  return res.data;
}
```

### 5.3 Hook for search state

`frontend/src/hooks/useBountySearch.ts`:

```ts
import { useEffect, useState } from "react";
import { BountyProgram } from "../types/bountyProgram";
import { fetchBountyPrograms } from "../api/bountyProgramsApi";

export interface SearchFilters {
  minBounty?: number;
  maxBounty?: number;
  platform?: string;
  rewardType?: string;
  search?: string;
}

export function useBountySearch(initial: SearchFilters = {}) {
  const [filters, setFilters] = useState<SearchFilters>(initial);
  const [results, setResults] = useState<BountyProgram[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function load() {
    setLoading(true);
    setError(null);
    try {
      const data = await fetchBountyPrograms(filters);
      setResults(data);
    } catch (err: any) {
      setError(err?.message || "Failed to fetch programs");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [JSON.stringify(filters)]);

  return { filters, setFilters, results, loading, error, reload: load };
}
```

### 5.4 Main components

`frontend/src/components/SearchForm.tsx`:

```tsx
import React, { FormEvent } from "react";
import { SearchFilters } from "../hooks/useBountySearch";

interface Props {
  filters: SearchFilters;
  onChange: (filters: SearchFilters) => void;
}

const SearchForm: React.FC<Props> = ({ filters, onChange }) => {
  function handleSubmit(e: FormEvent) {
    e.preventDefault();
  }

  return (
    <form onSubmit={handleSubmit} className="search-form">
      {/* Keyword search */}
      <input
        type="text"
        placeholder="Search by name or scope..."
        value={filters.search ?? ""}
        onChange={(e) => onChange({ ...filters, search: e.target.value })}
      />

      {/* Min bounty */}
      <input
        type="number"
        placeholder="Min bounty (USD)"
        value={filters.minBounty ?? ""}
        onChange={(e) =>
          onChange({
            ...filters,
            minBounty: e.target.value ? Number(e.target.value) : undefined
          })
        }
      />

      {/* Max bounty */}
      <input
        type="number"
        placeholder="Max bounty (USD)"
        value={filters.maxBounty ?? ""}
        onChange={(e) =>
          onChange({
            ...filters,
            maxBounty: e.target.value ? Number(e.target.value) : undefined
          })
        }
      />

      {/* Platform */}
      <input
        type="text"
        placeholder="Platform (HackerOne, Bugcrowd...)"
        value={filters.platform ?? ""}
        onChange={(e) => onChange({ ...filters, platform: e.target.value })}
      />

      {/* Reward type */}
      <select
        value={filters.rewardType ?? ""}
        onChange={(e) =>
          onChange({
            ...filters,
            rewardType: e.target.value || undefined
          })
        }
      >
        <option value="">Any reward type</option>
        <option value="cash">Cash</option>
        <option value="swag">Swag</option>
        <option value="points">Points</option>
      </select>
    </form>
  );
};

export default SearchForm;
```

`frontend/src/components/BountyProgramCard.tsx`:

```tsx
import React from "react";
import { BountyProgram } from "../types/bountyProgram";

interface Props {
  program: BountyProgram;
}

const BountyProgramCard: React.FC<Props> = ({ program }) => {
  const min = program.minBounty
    ? `$${(program.minBounty / 100).toFixed(2)}`
    : "N/A";
  const max = program.maxBounty
    ? `$${(program.maxBounty / 100).toFixed(2)}`
    : "N/A";

  return (
    <div className="bounty-card">
      <h3>
        <a href={program.url} target="_blank" rel="noreferrer">
          {program.name}
        </a>
      </h3>
      <p>
        <strong>Platform:</strong> {program.platform ?? "Unknown"}
      </p>
      <p>
        <strong>Reward:</strong> {min} - {max} {program.rewardType ?? ""}
      </p>
      <p>
        <strong>Scope:</strong> {program.scopeSummary ?? "No summary available"}
      </p>
      <p>
        <strong>Ease of entry:</strong> {program.easeOfEntry ?? "Unknown"}
      </p>

